# Define a function to add a contact to the phone book
def add_contact():
    name = input("Enter the name of the contact: ")
    phone_number = input("Enter the phone number: ")
    phone_book[name] = phone_number
    print(f"Contact added: {name} - {phone_number}")

# Define a function to view all contacts in the phone book
def view_contacts():
    if phone_book:
        print("Contacts in the phone book:")
        for name, number in phone_book.items():
            print(f"- {name}: {number}")
    else:
        print("The phone book is empty.")

# Define a function to delete a contact from the phone book
def delete_contact():
    name_to_delete = input("Enter the name of the contact to delete: ")
    if name_to_delete in phone_book:
        del phone_book[name_to_delete]
        print(f"Contact deleted: {name_to_delete}")
    else:
        print(f"Contact {name_to_delete} not found in the phone book.")

# Initialize the phone book with an empty dictionary
phone_book = {}

# Main loop to manage the phone book
while True:
    print("\nPhone Book Management System")
    print("1. Add Contact")
    print("2. View Contacts")
    print("3. Delete Contact")
    print("4. Exit")

    choice = input("Enter your choice: ")

    if choice == "1":
        add_contact()
    elif choice == "2":
        view_contacts()
    elif choice == "3":
        delete_contact()
    elif choice == "4":
        print("Exiting the phone book management system...")
        break
    else:
        print("Invalid choice. Please try again.")
